(657476, 68663, 17574, '<td valign="top">Can you tell that one cow to move a little to the right?</td>', 'Can you tell that one cow to move a little to the right?', '2004-04-07 14:13:16.000000', NULL, 1),
(657479, 68353, 18484, '<td valign="top">great perspective</td>', 'great perspective', '2004-04-07 14:13:36.000000', NULL, 1),
