(657507, 68345, 18484, '<td valign="top">great composition.</td>', 'great composition.', '2004-04-07 14:18:42.000000', NULL, 1),
(657508, 68747, 19608, '<td valign="top">Nice idea.  Sepia works well.  A couple suggestions:  USe a tripod and stop way down to get maximum DOF (if you didn''t) and position the lighting to remove the very bright hot spots on the right side.</td>', 'Nice idea.  Sepia works well.  A couple suggestions:  USe a tripod and stop way down to get maximum DOF (if you didn''t) and position the lighting to remove the very bright hot spots on the right side.', '2004-04-07 14:18:46.000000', NULL, 1),
(657509, 68555, 327, '<td valign="top">Bikes the topic I love the best. I do think the sunlight is killing your shot. Because of buildings, and the available light you might of tried shooting this at a different angle or a different time of day.</td>', 'Bikes the topic I love the best. I do think the sunlight is killing your shot. Because of buildings, and the available light you might of tried shooting this at a different angle or a different time of day.', '2004-04-07 14:19:03.000000', NULL, 1),
