INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(659572, 68652, 16965, '<td valign="top">interesting shot, I like the idea, but the hotshot on the hub is a bit distracting.  maybe moving the camera an inch or two to the right would have put the hub on the thirds line, and would have eliminated that hot spot.</td>', 'interesting shot, I like the idea, but the hotshot on the hub is a bit distracting.  maybe moving the camera an inch or two to the right would have put the hub on the thirds line, and would have eliminated that hot spot.', '2004-04-08 13:28:56.000000', NULL, 1),
(659573, 68755, 16965, '<td valign="top">interesting perspective, the wood flooring is a bit much.  I lke the long shadows.</td>', 'interesting perspective, the wood flooring is a bit much.  I lke the long shadows.', '2004-04-08 13:29:30.000000', NULL, 1),
(659574, 68502, 16965, '<td valign="top">I like this effect, but the hot spot in the reflection is really distracting.  I would have gone for a slightly longer exposure, and let the tire travel into the right third of the frame.</td>', 'I like this effect, but the hot spot in the reflection is really distracting.  I would have gone for a slightly longer exposure, and let the tire travel into the right third of the frame.', '2004-04-08 13:33:11.000000', NULL, 1),
(659576, 68094, 16965, '<td valign="top">nice image, but your wheel is completely hidden in darkness.  better lighting or a different angle would have brought forward as a stronger subject.</td>', 'nice image, but your wheel is completely hidden in darkness.  better lighting or a different angle would have brought forward as a stronger subject.', '2004-04-08 13:34:34.000000', NULL, 1),
