(661058, 68251, 19873, '<td valign="top">Great looking train wheel. I thought they are usually silver. Have not seen one in white before.</td>', 'Great looking train wheel. I thought they are usually silver. Have not seen one in white before.', '2004-04-09 16:14:51.000000', NULL, 1),
(661060, 67814, 19873, '<td valign="top">Simple and stark. Good job!</td>', 'Simple and stark. Good job!', '2004-04-09 16:16:14.000000', NULL, 1),
(661062, 68733, 19873, '<td valign="top">Looks like a flower. Very delicate and strong at the same time.</td>', 'Looks like a flower. Very delicate and strong at the same time.', '2004-04-09 16:17:32.000000', NULL, 1),
(661064, 68366, 19873, '<td valign="top">Nice angle and interesting subject too.</td>', 'Nice angle and interesting subject too.', '2004-04-09 16:20:24.000000', NULL, 1),
(661065, 68156, 19873, '<td valign="top">A sense of abandonment and futility is the feeling I have when I see this picture. Great photo!</td>', 'A sense of abandonment and futility is the feeling I have when I see this picture. Great photo!', '2004-04-09 16:21:40.000000', NULL, 1),
(661066, 68766, 15129, '<td valign="top">This could be neat in black and white, IMHO. As it is, it seems too busy (too many distracting items in the picture), and the sky is pretty washed out. I like the idea</td>', 'This could be neat in black and white, IMHO. As it is, it seems too busy (too many distracting items in the picture), and the sky is pretty washed out. I like the idea', '2004-04-09 16:21:43.000000', NULL, 1),
