(661071, 67883, 19873, '<td valign="top">I think the angle for this shot could be more interesting than this.</td>', 'I think the angle for this shot could be more interesting than this.', '2004-04-09 16:25:23.000000', NULL, 1),
(661073, 68735, 19873, '<td valign="top">I was going to ask how you photographed them with one not moving and then I realised that it could be you had stuck it down from behind. Interesting effect.</td>', 'I was going to ask how you photographed them with one not moving and then I realised that it could be you had stuck it down from behind. Interesting effect.', '2004-04-09 16:26:32.000000', NULL, 1),
(661074, 68669, 19873, '<td valign="top">I am not sure that this is related to a wheel or wheels.</td>', 'I am not sure that this is related to a wheel or wheels.', '2004-04-09 16:27:02.000000', NULL, 1),
