(661507, 68362, 18349, '<td valign="top">Great action shot...I''d only crop the top and bottom a little.</td>', 'Great action shot...I''d only crop the top and bottom a little.', '2004-04-10 01:18:59.000000', NULL, 1),
(661508, 68008, 18349, '<td valign="top">Unique</td>', 'Unique', '2004-04-10 01:19:16.000000', NULL, 1),
