INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(662446, 67640, 18722, '<td valign="top">Seems a bit out of focus and a tad dark.</td>', 'Seems a bit out of focus and a tad dark.', '2004-04-11 01:41:04.000000', NULL, 1),
(662447, 67982, 18722, '<td valign="top">A bit of an odd angle.</td>', 'A bit of an odd angle.', '2004-04-11 01:41:58.000000', NULL, 1),
(662451, 68438, 18722, '<td valign="top">Too bad the beautiful looking day created such harsh shadows.</td>', 'Too bad the beautiful looking day created such harsh shadows.', '2004-04-11 01:44:21.000000', NULL, 1),
(662453, 68394, 18722, '<td valign="top">The soft focus adds to the feel of looking back into the past, but I would have liked more contrast on the spokes.</td>', 'The soft focus adds to the feel of looking back into the past, but I would have liked more contrast on the spokes.', '2004-04-11 01:46:17.000000', NULL, 1),
(662458, 68590, 18722, '<td valign="top">A bit more depth of field would have been nice, just enough to get the entire truck in focus.</td>', 'A bit more depth of field would have been nice, just enough to get the entire truck in focus.', '2004-04-11 01:48:52.000000', NULL, 1),
(662461, 68028, 18722, '<td valign="top">I do not like the harsh shadows.</td>', 'I do not like the harsh shadows.', '2004-04-11 01:51:21.000000', NULL, 1),
(662462, 68732, 18722, '<td valign="top">The door is open inviting a view in, but it is too dark to see the interior.  More contrast between the shadow underneath and the tires would have been nice.</td>', 'The door is open inviting a view in, but it is too dark to see the interior.  More contrast between the shadow underneath and the tires would have been nice.', '2004-04-11 01:54:25.000000', NULL, 1),
(662464, 68716, 9462, '<td valign="top">lol... nice progression. Wish the sky wasn''t so washed.</td>', 'lol... nice progression. Wish the sky wasn''t so washed.', '2004-04-11 01:56:06.000000', NULL, 1),
(662465, 68344, 18722, '<td valign="top">The color seems a bit off.  Nice change for the ordinary ''wheel''.</td>', 'The color seems a bit off.  Nice change for the ordinary ''wheel''.', '2004-04-11 01:57:25.000000', NULL, 1),
(662466, 68523, 18722, '<td valign="top">A tighter crop would have worked much better.</td>', 'A tighter crop would have worked much better.', '2004-04-11 01:59:37.000000', NULL, 1),
(662468, 68006, 9462, '<td valign="top">nice perspective</td>', 'nice perspective', '2004-04-11 02:01:22.000000', NULL, 1),
(662469, 68545, 18722, '<td valign="top">The lighting is way off.  If it was your intention; sorry, but it does not work for me.</td>', 'The lighting is way off.  If it was your intention; sorry, but it does not work for me.', '2004-04-11 02:01:39.000000', NULL, 1),
(662470, 68339, 18722, '<td valign="top">too dark to make out much detail of the wheels.</td>', 'too dark to make out much detail of the wheels.', '2004-04-11 02:02:29.000000', NULL, 1),
(662472, 68611, 18722, '<td valign="top">Shadows are too harsh.</td>', 'Shadows are too harsh.', '2004-04-11 02:03:17.000000', NULL, 1),
(662473, 68626, 18722, '<td valign="top">Looks a bit out of focus, but that could be from the size.  It really needs to be bigger.</td>', 'Looks a bit out of focus, but that could be from the size.  It really needs to be bigger.', '2004-04-11 02:04:25.000000', NULL, 1),
(662474, 68654, 18722, '<td valign="top">In this one, the shadow on the wall works, but the shadows on the bike do not.  Otherwise, I like it.</td>', 'In this one, the shadow on the wall works, but the shadows on the bike do not.  Otherwise, I like it.', '2004-04-11 02:05:19.000000', NULL, 1),
(662475, 68006, 18722, '<td valign="top">A very odd perspective -- unless you have been run over recently!  :D</td>', 'A very odd perspective -- unless you have been run over recently!  :D', '2004-04-11 02:06:07.000000', NULL, 1),
(662476, 68312, 18722, '<td valign="top">The challenge objects, wheels, are hidden in shadow.</td>', 'The challenge objects, wheels, are hidden in shadow.', '2004-04-11 02:07:11.000000', NULL, 1),
(662477, 68710, 18722, '<td valign="top">Very blue.  Since it could be the natural lighting of the event I am not considering it, although it is distracting.</td>', 'Very blue.  Since it could be the natural lighting of the event I am not considering it, although it is distracting.', '2004-04-11 02:08:20.000000', NULL, 1),
(662478, 68753, 18722, '<td valign="top">More contrast would have been nice.</td>', 'More contrast would have been nice.', '2004-04-11 02:10:36.000000', NULL, 1),
(662479, 68276, 18722, '<td valign="top">I like this.  The sharpening may have been overdone, but I think it adds an old tin-print feel to the picture.</td>', 'I like this.  The sharpening may have been overdone, but I think it adds an old tin-print feel to the picture.', '2004-04-11 02:11:41.000000', NULL, 1),
(662481, 68456, 18722, '<td valign="top">Seems a bit grainy in the browns and I wish you could have done something with the sharp shadows.  But I like it.</td>', 'Seems a bit grainy in the browns and I wish you could have done something with the sharp shadows.  But I like it.', '2004-04-11 02:13:15.000000', NULL, 1),
(662483, 68679, 9462, '<td valign="top">Took me a sec:) Would be a cool to do an optical mouse in darkness for an antipole pair.</td>', 'Took me a sec:) Would be a cool to do an optical mouse in darkness for an antipole pair.', '2004-04-11 02:14:20.000000', NULL, 1),
(662484, 68738, 18722, '<td valign="top">Very simple!  Works very well.  Might be just a bit of overexposure on the string and top of the Yo-Yo.</td>', 'Very simple!  Works very well.  Might be just a bit of overexposure on the string and top of the Yo-Yo.', '2004-04-11 02:14:29.000000', NULL, 1),
(662486, 68594, 18722, '<td valign="top">Very nice!</td>', 'Very nice!', '2004-04-11 02:15:20.000000', NULL, 1),
(662489, 68189, 18722, '<td valign="top">If You could have found a way to remove yourself from the photo it would have been better, add a bit more contrast between the shadowed sides of the blades and the background and it could have been great.</td>', 'If You could have found a way to remove yourself from the photo it would have been better, add a bit more contrast between the shadowed sides of the blades and the background and it could have been great.', '2004-04-11 02:17:31.000000', NULL, 1),
