(662533, 68595, 18722, '<td valign="top">I like it except fo the ''hot'' spots.</td>', 'I like it except fo the ''hot'' spots.', '2004-04-11 02:51:22.000000', NULL, 1),
(662535, 68652, 18722, '<td valign="top">Too dark on the lower left.</td>', 'Too dark on the lower left.', '2004-04-11 02:52:28.000000', NULL, 1),
