(662540, 68581, 18722, '<td valign="top">Interesting perspective.</td>', 'Interesting perspective.', '2004-04-11 02:55:15.000000', NULL, 1),
(662541, 68695, 18722, '<td valign="top">I do not get the title.  Teh shadows are too distracting and the coloring seems off.</td>', 'I do not get the title.  Teh shadows are too distracting and the coloring seems off.', '2004-04-11 02:56:32.000000', NULL, 1),
(662543, 68289, 18722, '<td valign="top">Not enough light on the tires.</td>', 'Not enough light on the tires.', '2004-04-11 02:58:04.000000', NULL, 1),
(662544, 67938, 18722, '<td valign="top">Too small, but otherwise seems good.  Would have really liked this to have been full sized.</td>', 'Too small, but otherwise seems good.  Would have really liked this to have been full sized.', '2004-04-11 02:58:45.000000', NULL, 1),
(662546, 67883, 18722, '<td valign="top">The hot spot is distracting.</td>', 'The hot spot is distracting.', '2004-04-11 02:59:24.000000', NULL, 1),
(662547, 68298, 18722, '<td valign="top">Not enough contrast between the tire and the shadows behind it.</td>', 'Not enough contrast between the tire and the shadows behind it.', '2004-04-11 02:59:52.000000', NULL, 1),
(662548, 68362, 15407, '<td valign="top">A rare shot ,this! He sure didn''t get many laps with the LAME !!! car.  Hope they can get him back in the hunt! Very nice shot...  Looks like you must have had ''Pro'' credintials to get this close to the action... Get any sand in your camera or did you stick with one lens?</td>', 'A rare shot ,this! He sure didn''t get many laps with the LAME !!! car.  Hope they can get him back in the hunt! Very nice shot...  Looks like you must have had ''Pro'' credintials to get this close to the action... Get any sand in your camera or did you stick with one lens?', '2004-04-11 03:00:41.000000', NULL, 1),
(662549, 68137, 18722, '<td valign="top">Too small, and seems over exposed.</td>', 'Too small, and seems over exposed.', '2004-04-11 03:02:20.000000', NULL, 1),
(662551, 68699, 18722, '<td valign="top">Good</td>', 'Good', '2004-04-11 03:03:28.000000', NULL, 1),
(662552, 68686, 18722, '<td valign="top">I would have liked the lighting to be consistent across the image.</td>', 'I would have liked the lighting to be consistent across the image.', '2004-04-11 03:04:45.000000', NULL, 1),
(662553, 68602, 18722, '<td valign="top">Too small.</td>', 'Too small.', '2004-04-11 03:09:45.000000', NULL, 1),
(662555, 68544, 18722, '<td valign="top">The hot spot is very distracting.</td>', 'The hot spot is very distracting.', '2004-04-11 03:11:29.000000', NULL, 1),
