(665713, 68602, 15919, '<td valign="top">Interesting possition and overal the image seem pretty good and technically well performed.  Cant you make it bigger.</td>', 'Interesting possition and overal the image seem pretty good and technically well performed.  Cant you make it bigger.', '2004-04-13 13:12:39.000000', NULL, 1),
(665714, 68685, 18960, '<td valign="top">That''s cool. A great, creative way to use a bike.</td>', 'That''s cool. A great, creative way to use a bike.', '2004-04-13 13:15:09.000000', NULL, 1),
(665716, 68603, 15919, '<td valign="top">Very good angel, great exposure and technically very good overall.  Hope you´ve put some explanations of how you did this wich can be looked at at the end of the challenge.</td>', 'Very good angel, great exposure and technically very good overall.  Hope you´ve put some explanations of how you did this wich can be looked at at the end of the challenge.', '2004-04-13 13:15:30.000000', NULL, 1),
(665718, 68125, 18960, '<td valign="top">For me, not enough wheel.</td>', 'For me, not enough wheel.', '2004-04-13 13:16:15.000000', NULL, 1),
