INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(665791, 68400, 18960, '<td valign="top">Good idea.</td>', 'Good idea.', '2004-04-13 14:09:40.000000', NULL, 1),
(665792, 68159, 18960, '<td valign="top">Rats. This is about the hundreth one I''ve seen.</td>', 'Rats. This is about the hundreth one I''ve seen.', '2004-04-13 14:10:19.000000', NULL, 1),
(665793, 68718, 18960, '<td valign="top">Somewhat common (looks like something I would do), and I don''t have a clue how to make it better.</td>', 'Somewhat common (looks like something I would do), and I don''t have a clue how to make it better.', '2004-04-13 14:13:01.000000', NULL, 1),
(665794, 67980, 18960, '<td valign="top">The subject remains interesting even though there are several entries for old wagon wheels, and the color and your composition make it good.</td>', 'The subject remains interesting even though there are several entries for old wagon wheels, and the color and your composition make it good.', '2004-04-13 14:15:28.000000', NULL, 1),
(665796, 67631, 18960, '<td valign="top">Cleaned up gears would have been more interesting to me, all bright and greasy.</td>', 'Cleaned up gears would have been more interesting to me, all bright and greasy.', '2004-04-13 14:17:14.000000', NULL, 1),
(665797, 68179, 11486, '<td valign="top">Realy cool light and shadows!</td>', 'Realy cool light and shadows!', '2004-04-13 14:17:29.000000', NULL, 1),
(665798, 68540, 11486, '<td valign="top">Slightly unfocused, but the idea is better than the result</td>', 'Slightly unfocused, but the idea is better than the result', '2004-04-13 14:19:22.000000', NULL, 1),
(665800, 68218, 11486, '<td valign="top">Dramatic light from the flames. Any casualties?</td>', 'Dramatic light from the flames. Any casualties?', '2004-04-13 14:20:10.000000', NULL, 1),
(665801, 68686, 11486, '<td valign="top">Dramatic light and a great idea!</td>', 'Dramatic light and a great idea!', '2004-04-13 14:21:42.000000', NULL, 1),
(665802, 68668, 18960, '<td valign="top">Good idea and composition. But sort of a dreary b&amp;w rendition.</td>', 'Good idea and composition. But sort of a dreary b&w rendition.', '2004-04-13 14:21:42.000000', NULL, 1),
(665805, 68119, 18960, '<td valign="top">I like the wheels but on my monitor the blacks arent as deep as they should be, or maybe its just soft in the wrong places.</td>', 'I like the wheels but on my monitor the blacks arent as deep as they should be, or maybe its just soft in the wrong places.', '2004-04-13 14:24:24.000000', NULL, 1),
(665811, 68560, 18960, '<td valign="top">Nice old wheel. I''d like the saturation turned up a bit.</td>', 'Nice old wheel. I''d like the saturation turned up a bit.', '2004-04-13 14:27:58.000000', NULL, 1),
(665813, 68262, 18960, '<td valign="top">Nay</td>', 'Nay', '2004-04-13 14:28:44.000000', NULL, 1),
(665820, 68603, 19708, '<td valign="top">Great capture here. The composition and motion a the key to making this a great shot. Well done!</td>', 'Great capture here. The composition and motion a the key to making this a great shot. Well done!', '2004-04-13 14:32:00.000000', NULL, 1),
(665821, 68534, 18960, '<td valign="top">Thanks for the close-up, and I like your composition. I wonder what it is? Seems a contradiction. Oxidized iron but it''s bright and shiny.</td>', 'Thanks for the close-up, and I like your composition. I wonder what it is? Seems a contradiction. Oxidized iron but it''s bright and shiny.', '2004-04-13 14:32:37.000000', NULL, 1),
(665831, 68543, 18960, '<td valign="top">Nice discovery. Composition could have been better, although it might have been dangerous climbing around to get the shot. At least we got the image of these spare tires.</td>', 'Nice discovery. Composition could have been better, although it might have been dangerous climbing around to get the shot. At least we got the image of these spare tires.', '2004-04-13 14:37:26.000000', NULL, 1),
(665832, 67862, 18960, '<td valign="top">Creative title.</td>', 'Creative title.', '2004-04-13 14:38:16.000000', NULL, 1),
(665835, 68732, 18960, '<td valign="top">Cars kind of leave me flat.</td>', 'Cars kind of leave me flat.', '2004-04-13 14:39:00.000000', NULL, 1),
(665839, 68592, 18960, '<td valign="top">There must be tires hiding in there. I don''t like the head on composition, but I do like the contrast and the bit of humor.</td>', 'There must be tires hiding in there. I don''t like the head on composition, but I do like the contrast and the bit of humor.', '2004-04-13 14:41:03.000000', NULL, 1),
(665844, 68523, 18960, '<td valign="top">This is one of the most impressive water wheels and the lighting (etc., etc.) is perfect. Your frame sucks.</td>', 'This is one of the most impressive water wheels and the lighting (etc., etc.) is perfect. Your frame sucks.', '2004-04-13 14:43:34.000000', NULL, 1),
(665849, 68735, 18960, '<td valign="top">Clever. Dumb subjects but nice creative idea.</td>', 'Clever. Dumb subjects but nice creative idea.', '2004-04-13 14:45:12.000000', NULL, 1),
(665850, 68556, 11486, '<td valign="top">I was thinking about something similar, but this is better than what i could have done...</td>', 'I was thinking about something similar, but this is better than what i could have done...', '2004-04-13 14:45:19.000000', NULL, 1),
(665852, 68763, 18960, '<td valign="top">Nope.</td>', 'Nope.', '2004-04-13 14:45:47.000000', NULL, 1),
